#include <P1AM.h>

#define START_PB 1
#define STOP_PB 2
const int IN_SLOT = 1;
const int OUT_SLOT = 2;
const int MOTOR = 1;
bool running = false;

void setup() {
  while (!P1.init()) {
    ;   // wait for the modules
  }
}

void loop() {
  bool startPressed = P1.readDiscrete(IN_SLOT, START_PB) == HIGH;
  bool stopPressed = P1.readDiscrete(IN_SLOT, STOP_PB) == LOW;   // NC
  running = (startPressed || running) && !stopPressed;
  P1.writeDiscrete(running, OUT_SLOT, MOTOR);
}

