#include <P1AM.h>

bool running = false;
bool lastRunning = false;

void setup() {
  while (!P1.init()) {
    ;   // wait for the modules
  }
  Serial.begin(115200);
}

void loop() {
  bool start = P1.readDiscrete(1, 1);    // Start: NO
  bool stopOk = P1.readDiscrete(1, 2);   // Stop: NC, ON when not pressed
  running = (start || running) && stopOk;
  if (running != lastRunning) {
    Serial.println(running ? "Motor ON" : "Motor OFF");
    lastRunning = running;
  }
  P1.writeDiscrete(running, 2, 1);
}

